CREATE TABLE `audit_events` (
	`seq` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`operation_id` text NOT NULL,
	`actor` text NOT NULL,
	`actor_role` text NOT NULL,
	`entity` text NOT NULL,
	`record_id` text NOT NULL,
	`action` text NOT NULL,
	`before_json` text,
	`after_json` text,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
--> statement-breakpoint
CREATE INDEX `audit_entity_record` ON `audit_events` (`entity`,`record_id`);--> statement-breakpoint
CREATE INDEX `audit_date` ON `audit_events` (`created_at`);--> statement-breakpoint
CREATE INDEX `audit_operation` ON `audit_events` (`operation_id`);--> statement-breakpoint
CREATE TABLE `backup_catalog` (
	`id` text PRIMARY KEY NOT NULL,
	`object_key` text NOT NULL,
	`sha256` text NOT NULL,
	`bytes` integer NOT NULL,
	`actor` text NOT NULL,
	`summary_json` text NOT NULL,
	`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL
);
--> statement-breakpoint
CREATE TABLE `monitor_buckets` (
	`key` text PRIMARY KEY NOT NULL,
	`hour` text NOT NULL,
	`route` text NOT NULL,
	`status` integer NOT NULL,
	`requests` integer DEFAULT 0 NOT NULL,
	`duration_ms` integer DEFAULT 0 NOT NULL,
	`max_ms` integer DEFAULT 0 NOT NULL
);
--> statement-breakpoint
CREATE INDEX `monitor_hour` ON `monitor_buckets` (`hour`);
